<style>
:root{color-scheme:light;--auth-blue:#0d6efd;--auth-dark:#0f172a;--auth-muted:#64748b;--auth-border:#dce4ef}
*{box-sizing:border-box}body.auth-page{margin:0;font-family:Arial,Helvetica,sans-serif;color:var(--auth-dark);background:radial-gradient(ellipse at 10% 10%,#e9f2ff,transparent 45%),#f8fafc;font-size:15px;line-height:1.55;min-height:100vh}
.auth-page a{color:var(--auth-blue);text-decoration:none}.auth-page a:hover{text-decoration:underline}.auth-header{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:22px clamp(16px,3vw,52px);max-width:1600px;margin:0 auto}
.auth-brand{display:flex;gap:12px;align-items:center;font-size:1.14rem;font-weight:800;color:var(--auth-dark)!important;min-width:0;overflow-wrap:anywhere}.auth-brand small{display:block;font-size:.72rem;font-weight:400;color:var(--auth-muted)}
.brand-mark{display:grid;place-items:center;background:linear-gradient(135deg,#0d6efd,#63a4ff);color:white;border-radius:14px;width:44px;height:44px;flex-shrink:0}.back-link{font-size:.88rem;white-space:nowrap}
.auth-shell{display:grid;grid-template-columns:minmax(0,.95fr) minmax(0,1.05fr);max-width:1100px;margin:24px auto 20px;background:white;border:1px solid var(--auth-border);border-radius:28px;overflow:hidden;box-shadow:0 20px 70px #0f172a0c;width:calc(100% - 48px)}
.auth-story{background:radial-gradient(circle at 100% 20%,#67a3ff70,transparent 50%),linear-gradient(155deg,#0d6efd,#0742aa);color:#fff;padding:48px 38px;display:flex;flex-direction:column;justify-content:space-between;gap:36px;position:relative}
.story-label{display:inline-block;letter-spacing:.14em;font-weight:700;font-size:.68rem;border:1px solid #ffffff4d;background:#ffffff12;padding:7px 12px;border-radius:30px}
.auth-story h2{font-size:clamp(1.9rem,3vw,2.6rem);line-height:1.17;letter-spacing:-.03em;margin:25px 0 16px}.auth-story p{color:#e4eeff;margin:0;max-width:330px;font-size:.98rem;line-height:1.7}
.story-cards{display:grid;gap:12px}.story-card{display:flex;align-items:center;gap:14px;padding:18px;border:1px solid #ffffff33;border-radius:18px;background:#ffffff0f}
.story-icon{width:40px;height:40px;display:grid;place-items:center;background:#ffffff20;border-radius:12px;font-size:1.55rem;flex-shrink:0}.story-card strong{display:block;font-size:.94rem}.story-card small{display:block;color:#e4eeff;font-size:.78rem;margin-top:3px}.story-footer{font-size:.72rem;color:#d9e8ff}
.auth-form-panel{padding:42px clamp(22px,3.5vw,52px);min-width:0}.form-eyebrow{color:var(--auth-blue);text-transform:uppercase;font-size:.72rem;font-weight:700;letter-spacing:.12em;margin:0 0 10px}.auth-form-panel h1{font-size:2rem;line-height:1.2;margin:0 0 10px;letter-spacing:-.04em}.form-intro{color:var(--auth-muted);margin:0 0 26px;line-height:1.65}
.auth-form{display:grid;gap:18px}.field{min-width:0}.field label{display:block;font-size:.86rem;font-weight:700;margin-bottom:7px}.field label .optional{font-size:.76rem;font-weight:400;color:var(--auth-muted)}
.field input,.field textarea{width:100%;min-width:0;border:1px solid var(--auth-border);border-radius:11px;padding:12px 13px;font:inherit;color:var(--auth-dark);background:#fff;outline:none;min-height:46px}.field textarea{resize:vertical;min-height:80px}.field input:focus,.field textarea:focus{border-color:var(--auth-blue);box-shadow:0 0 0 3px #0d6efd18}.field input::placeholder,.field textarea::placeholder{color:#8b97a8;font-size:.88rem}
.password-wrap{display:flex;border:1px solid var(--auth-border);border-radius:11px;overflow:hidden;align-items:center}.password-wrap:focus-within{border-color:var(--auth-blue);box-shadow:0 0 0 3px #0d6efd18}.password-wrap input{border:0;border-radius:0}.password-wrap input:focus{box-shadow:none}.password-toggle{background:transparent;border:0;color:#0b5ed7;font:inherit;font-size:.75rem;font-weight:700;padding:12px;cursor:pointer;flex-shrink:0}.password-toggle[hidden]{display:none}
.field-note{font-size:.75rem;color:var(--auth-muted);margin:6px 0 0}.form-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.submit-btn{width:100%;border:0;border-radius:12px;color:#fff;background:var(--auth-blue);font:inherit;font-weight:700;min-height:48px;padding:12px 16px;cursor:pointer;margin-top:2px}.submit-btn:hover{background:#0b5ed7}.submit-btn:focus-visible,.password-toggle:focus-visible,a:focus-visible{outline:3px solid #70acff;outline-offset:3px}
.form-switch{font-size:.88rem;color:var(--auth-muted);text-align:center;margin:24px 0 0;padding-top:20px;border-top:1px solid #edf1f7}.form-switch a{font-weight:700}.auth-alert{padding:13px 15px;border-radius:12px;margin:0 0 18px;font-size:.86rem;overflow-wrap:anywhere}.auth-alert ul{margin:0;padding-left:18px}.auth-alert-error{color:#991b1b;background:#fef2f2;border:1px solid #fecaca}.auth-alert-success{color:#166534;background:#f0fdf4;border:1px solid #bbf7d0}.auth-footer{text-align:center;color:var(--auth-muted);font-size:.75rem;padding:12px 16px 28px}
@media(min-width:1200px){.auth-shell{margin-top:40px}}
@media(max-width:767.98px){.auth-header{padding:18px 16px}.auth-brand{font-size:1rem}.auth-brand small{display:none}.back-link{font-size:.75rem}.auth-shell{grid-template-columns:1fr;width:calc(100% - 28px);margin:12px auto 16px;border-radius:20px}.auth-story{display:none}.auth-form-panel{padding:30px 24px}.auth-form-panel h1{font-size:1.8rem}}
@media(max-width:420px){.form-row{grid-template-columns:1fr;gap:18px}.auth-form-panel{padding:26px 20px}.auth-header{gap:10px}.brand-mark{height:38px;width:38px}.auth-brand{gap:8px;font-size:.92rem}}
</style>
